const RES = "Resolution: items 1, 2 and 4 answered against `4231625`. Items 3 and 5 are answered by the owner decisions, witnessed against `fa4704e` (before) and at the commit that carries this change (after). Item 3, shallow CLI reference: the shared help text is the reference for client and mod verbs. The cli/client-*.txt files other than client-exec.txt are regenerated from client.txt and the cli/mod-*.txt files from mod.txt; the regeneration changed no bytes, and per-verb help is not re-fetched from a live jayzee run. client-exec.txt stays distinct. Item 5, engine clone omission: .jayzee/engine/api-reference.md is canonical and .jayzee/reference/engine/api-reference.md is regenerated from it (119,585 to 120,797 bytes, sha256 " + CANON + "). The engine INDEX and engine.yaml now record that sha256 in place of the two hashes that matched neither the file nor each other (31a39ac2c2689403920f92bf1231e382cae87c7c3f0055769e5fb0797a60f419 and b5d10e377d047b1f2d5d303009fe45757aad4abb66fa9ab2a32951676d93b630). The OPEN-023 witness value 08ce22c2 for engine.yaml was a transcription error: sha256sum gives 08ce22a45d7a264940155be27ddee0c45067ee8a28fb3cd7a3bd2a9c1f5df619. All five items are now answered; Status stays OPEN because the status vocabulary has no resolved value, as OPEN-001 records.";

const regen = await gm.run_shell({ command: "cd /workspace/cleetus/.jayzee/reference/cli && for f in client-*.txt; do [ \"$f\" = client-exec.txt ] || cp client.txt \"$f\"; done && for f in mod-*.txt; do cp mod.txt \"$f\"; done && cp /workspace/cleetus/.jayzee/engine/api-reference.md /workspace/cleetus/.jayzee/reference/engine/api-reference.md && echo REGEN-OK" });

const yaml = await gm.edit_file({ path: ROOT + '/.jayzee/engine/engine.yaml', old: 'sha256: b5d10e377d047b1f2d5d303009fe45757aad4abb66fa9ab2a32951676d93b630', new: 'sha256: ' + CANON });

const idxEdits = [];
idxEdits.push(await gm.edit_file({ path: IDX, old: 'engine.yaml sha256 31a39ac2c2689403920f92bf1231e382cae87c7c3f0055769e5fb0797a60f419', new: 'canonical api-reference.md sha256 ' + CANON }));
idxEdits.push(await gm.edit_file({ path: IDX, old: '| api-reference.md | 119585 | see section below |', new: '| api-reference.md | 120797 | see section below |' }));
idxEdits.push(await gm.edit_file({ path: IDX, old: '## api-reference.md headings (119585 bytes)', new: '## api-reference.md headings (120797 bytes)' }));

const cov = await gm.edit_file({ path: ROOT + '/.jayzee/reference/COVERAGE.md', old: 'api-reference.md (119,585 bytes), and 23 skill guides.', new: 'api-reference.md (120,797 bytes), and 23 skill guides.' });
const doc = await gm.edit_file({ path: ROOT + '/docs/OPEN-ITEMS.md', old: 'Resolution: items 1, 2 and 4 answered against `4231625`; items 3 and 5 restated above', new: RES });

return { regen, yaml, idxEdits, cov, doc };

const r = await Promise.all([
  gm.run_shell({ command: "cd /workspace/cleetus && echo '== AFTER sha256sum' && sha256sum .jayzee/engine/api-reference.md .jayzee/reference/engine/api-reference.md .jayzee/engine/engine.yaml .jayzee/reference/cli/client*.txt .jayzee/reference/cli/mod*.txt | sed 's#  .*/#  #'; echo '== AFTER canonical hash in INDEX and engine.yaml'; grep -c 'a7d8fa98dddf13acbda7cb6bcff978c6cfa2fcd4daa827ca012b918347a004ed' .jayzee/reference/engine/INDEX.md .jayzee/engine/engine.yaml; grep -c '31a39ac2c2689\\|b5d10e377d047' .jayzee/reference/engine/INDEX.md .jayzee/engine/engine.yaml; echo '== AFTER gap counts'; grep -n 'Total gaps reported' .jayzee/reference/COVERAGE.md; node scripts/check-open-items.mjs; echo \"exit=$?\"" }),
  gm.run_shell({ command: "cd /workspace/cleetus && node scripts/check-ideal-coverage.mjs; echo \"exit=$?\"; node scripts/check-featureset.mjs > /tmp/fs.out 2>&1; echo \"featureset exit=$?\"; tail -n 1 /tmp/fs.out" }),
  gm.run_shell({ command: "cd /workspace/cleetus && npm run check > /tmp/npmcheck.out 2>&1; echo \"npm-check exit=$?\"; tail -n 12 /tmp/npmcheck.out | cut -c1-240" }),
  gm.run_shell({ command: "cd /workspace/cleetus && git status --short && echo '== diff --stat' && git diff --stat && echo '== client-exec vs client' && cmp -s .jayzee/reference/cli/client.txt .jayzee/reference/cli/client-exec.txt; echo \"distinct-exit=$?\"" }),
]);
return r.map(x => x.output);

